FICHES.append(fiche(
 id='asile-externalisation-rwanda', affirmation="Il faut envoyer les demandeurs d'asile au Rwanda, comme le Royaume-Uni.", volet='immigration', sous_theme='Immigration et asile',
 mots_cles=['rwanda demandeurs d asile', 'plan rwanda', 'externalisation asile', 'royaume uni rwanda', 'modele albanie', 'italie albanie migrants', 'sous traiter asile', 'envoyer migrants au rwanda'],
 verdict='trompeur', fiabilite='etabli',
 resume="Le Royaume-Uni n'a pas réussi à appliquer son plan Rwanda : la Cour suprême l'a jugé illégal à l'unanimité en 2023, et le gouvernement suivant l'a abandonné en 2024 après environ 700 millions de livres dépensés pour quatre volontaires envoyés, selon la ministre de l'Intérieur. Les traversées de la Manche ont varié sans effet dissuasif démontré. Le modèle italien en Albanie est resté presque vide pendant sa première année, bloqué par les juges.",
 contexte="Plusieurs responsables politiques en France et en Europe proposent de traiter les demandes d'asile hors d'Europe, sur le modèle britannique ou italien.",
 explication="Pour juger une politique, il faut regarder ce qu'elle a coûté, combien de personnes elle a concernées, si elle respecte le droit et si elle a réduit les arrivées.",
 sources=[A_NAO_RWANDA_2024, A_11KBW_COURSUPREME_2023, A_ITV_RWANDA_2024, A_MIGOBS_CHANNEL_2024, A_AFP_ALBANIE_2025, A_DAWN_ALBANIE_2026],
 faits=[
  fait("Selon le National Audit Office, le Royaume-Uni s'engageait à verser 370 M£ au Rwanda, plus 20 000 £ par personne et 120 M£ après les 300 premiers transferts, plus 150 874 £ par personne pour le traitement des dossiers.", 'a_nao_rwanda_2024', '2024', 'Royaume-Uni', "Le coût par personne était considérable.", 'etabli', '370 M£'),
  fait("Le 15 novembre 2023, la Cour suprême britannique a jugé à l'unanimité que le Rwanda n'était pas un pays sûr, en raison d'un risque réel de renvoi des demandeurs d'asile vers leur pays d'origine.", 'a_11kbw_coursupreme_2023', '2023', 'Royaume-Uni', "Le plan violait le principe de non-refoulement.", 'etabli'),
  fait("En juillet 2024, la ministre de l'Intérieur Yvette Cooper a déclaré que le plan abandonné avait coûté 700 M£, dont 290 M£ versés au Rwanda, pour envoyer seulement quatre volontaires.", 'a_itv_rwanda_2024', '2022-2024', 'Royaume-Uni', "Le plan n'a quasiment jamais fonctionné.", 'etabli', '700 M£'),
  fait("Selon le Migration Observatory (Oxford), les arrivées en petits bateaux sont passées de 46 000 en 2022 à environ 29 000 en 2023, puis ont augmenté de 16 % au premier semestre 2024 ; les preuves d'un effet dissuasif des restrictions du droit d'asile sont jugées peu convaincantes.", 'a_migobs_channel_2024', '2022-2024', 'Manche', "Les arrivées ont baissé en 2023 (fait défavorable), mais la baisse n'est pas attribuée au plan Rwanda et elle n'a pas duré.", 'estimation', '29 000 en 2023'),
  fait("Un an après leur ouverture en octobre 2024, les centres italiens en Albanie avaient reçu 132 personnes au total selon des ONG italiennes, les juges ayant à plusieurs reprises refusé les placements.", 'a_afp_albanie_2025', '2024-2025', 'Italie et Albanie', "Le modèle italien a été largement bloqué par le droit.", 'estimation', '132 personnes'),
  fait("En février 2026, le centre albanais accueillait environ 90 personnes après de nouveaux transferts, et l'Union européenne a adopté des règles facilitant les renvois vers des pays jugés « sûrs ».", 'a_dawn_albanie_2026', '2026', 'Italie, Albanie, Union européenne', "L'externalisation progresse dans le droit européen : la situation évolue (fait défavorable).", 'estimation'),
 ],
 court="Le Royaume-Uni a dépensé environ 700 millions de livres pour envoyer quatre volontaires au Rwanda, selon sa ministre de l'Intérieur. La Cour suprême avait jugé le plan illégal à l'unanimité, et il a été abandonné en 2024. Copier un échec coûteux n'est pas une politique.",
 moyen="Le plan Rwanda est un fiasco documenté. Le National Audit Office chiffrait un engagement de 370 M£, plus des sommes par personne. En novembre 2023, la Cour suprême a jugé à l'unanimité que le Rwanda n'était pas un pays sûr. En juillet 2024, le nouveau gouvernement a abandonné le plan : 700 M£ dépensés, quatre volontaires envoyés.\n\nLes arrivées par la Manche ont baissé en 2023, puis remonté en 2024, et les chercheurs d'Oxford ne trouvent pas de preuve solide d'un effet dissuasif. Le modèle italien en Albanie a lui aussi été bloqué par les juges pendant sa première année. Sous-traiter l'asile coûte cher, se heurte au droit et ne règle rien.",
 detaille="Le Royaume-Uni voulait envoyer au Rwanda des demandeurs d'asile arrivés irrégulièrement. Selon le National Audit Office, l'accord prévoyait 370 M£ versés au Rwanda, puis 20 000 £ par personne, 120 M£ après les 300 premiers transferts et 150 874 £ par personne pour le traitement des dossiers. Des sommes considérables pour un nombre limité de personnes.\n\nLe 15 novembre 2023, la Cour suprême a jugé à l'unanimité que le Rwanda n'était pas sûr : les demandeurs d'asile risquaient d'être renvoyés vers les pays qu'ils fuyaient. En juillet 2024, la ministre de l'Intérieur Yvette Cooper a annoncé que le plan abandonné avait coûté 700 M£, dont 290 M£ versés au Rwanda, pour quatre volontaires envoyés. Les arrivées en petits bateaux sont passées de 46 000 en 2022 à environ 29 000 en 2023, puis ont augmenté de 16 % au premier semestre 2024 ; le Migration Observatory juge peu convaincantes les preuves d'un effet dissuasif.\n\nL'Italie a tenté une variante en Albanie : 132 personnes envoyées en un an selon des ONG, des décisions de justice répétées contre les placements. Début 2026, le centre accueillait environ 90 personnes et l'Union européenne a assoupli ses règles sur les pays « sûrs » : le débat n'est pas clos. Mais l'expérience montre qu'une politique d'asile efficace passe par des procédures rapides et justes, des voies légales et la lutte contre les passeurs, pas par l'envoi de personnes à l'autre bout du monde.",
 empathie="Voir des bateaux traverser la Manche ou la Méditerranée donne un sentiment d'impuissance. Il est normal de chercher une solution radicale ; encore faut-il qu'elle marche.",
 legitimes=["Les traversées irrégulières sont dangereuses et enrichissent les passeurs.", "Les procédures d'asile sont longues et engorgées."],
 contre=[
  ("Le plan n'a pas marché parce que les juges l'ont bloqué.", "Les juges ont appliqué un principe de base du droit d'asile : ne pas renvoyer quelqu'un vers un pays où il risque la persécution ; un plan qui l'ignore ne peut pas fonctionner dans un État de droit."),
  ("L'Italie y arrive bien avec l'Albanie.", "Pendant sa première année, le centre albanais a reçu 132 personnes au total selon des ONG ; c'est très peu au regard des arrivées, et les juges ont bloqué de nombreux placements."),
 ],
 questions=["Savais-tu que le plan Rwanda a coûté environ 700 millions de livres pour quatre volontaires ?", "Combien serais-tu prêt à payer par personne pour une politique qui ne réduit pas les arrivées ?"],
 limites=["Le chiffre de 700 M£ et de quatre volontaires vient du gouvernement travailliste, opposé au plan ; il n'a pas été recoupé par le National Audit Office.", "L'arrêt de la Cour suprême a été lu à travers un compte rendu d'avocats ; la loi britannique adoptée ensuite pour contourner l'arrêt n'a pas été vérifiée.", "Le coût du protocole Italie-Albanie n'a été trouvé dans aucune source lue.", "Les arrivées dans la Manche après le premier semestre 2024 n'ont pas été vérifiées."],
 publics={'convaincus': "Ce n'est pas la gauche qui le dit : la Cour suprême britannique a jugé le plan illégal à l'unanimité, et environ 700 millions de livres ont été dépensés pour envoyer quatre volontaires. Les arrivées n'ont pas cessé pour autant. On peut vouloir de la fermeté et refuser de gaspiller l'argent public.",
  'indecis': "Les traversées dangereuses sont un vrai problème. Mais le Royaume-Uni a essayé l'externalisation : un coût énorme, un blocage juridique, presque personne envoyé, et un abandon en 2024. Des procédures d'asile rapides et la lutte contre les passeurs sont des pistes plus sérieuses."},
 a_actualiser='2027-06-30', raison="Mise en œuvre du pacte européen sur la migration et l'asile et bilan du centre albanais.",
))

