FICHES.append(fiche(
 id='riches-paient-impot-revenu', affirmation="Les 10 % les plus riches paient déjà presque tout l'impôt sur le revenu.", volet='economie', sous_theme='Fiscalité',
 mots_cles=['10 % les plus riches', 'riches paient tout', 'impot sur le revenu riches', 'concentration de l impot', 'les riches paient deja', 'matraquage fiscal riches', 'qui paie l impot', 'progressivite de l impot'],
 verdict='trompeur', fiabilite='etabli',
 resume="C'est vrai pour l'impôt sur le revenu : selon la DGFiP, les 10 % des foyers les plus aisés en paient environ les trois quarts. Mais cet impôt ne représente qu'environ 7 % de tous les impôts et taxes ; la TVA et la CSG, payées par tous, rapportent bien plus. Tous prélèvements confondus, l'Insee trouve un taux à peu près plat, légèrement dégressif aux extrémités, et l'IPP montre que les milliardaires paient proportionnellement moins que les 0,1 % les plus riches.",
 contexte="L'argument revient à chaque débat sur la taxation des hauts patrimoines, par exemple autour de la taxe Zucman ou du retour de l'ISF.",
 explication="Il faut distinguer un impôt précis (l'impôt sur le revenu, très concentré) de l'ensemble des prélèvements (TVA, CSG, cotisations, impôts sur les sociétés), et regarder le taux payé par rapport aux revenus, pas seulement les montants.",
 sources=[C_JDE_DGFIP_2025, C_OBSINEG_IR_2025, C_IPP_MILLIARDAIRES_2023, C_INSEE_REDIS_2023],
 faits=[
  fait("Selon la DGFiP, les 10 % des foyers les plus aisés acquittent 76 % de l'impôt sur le revenu net.", 'c_jde_dgfip_2025', '2023', 'France', "La concentration de l'impôt sur le revenu est réelle : c'est le point de départ honnête de la réponse.", 'etabli', '76 %'),
  fait("L'impôt sur le revenu rapporte environ 90 milliards d'euros, soit 7 % des quelque 1 200 milliards d'impôts et taxes ; la TVA rapporte plus du double et la CSG environ 150 milliards.", 'c_obsineg_ir_2025', '2023-2025', 'France', "L'impôt sur le revenu n'est qu'une petite partie de ce que paient les ménages.", 'etabli', '7 %'),
  fait("Selon l'Insee, l'ensemble des prélèvements représente un taux voisin de 55 % des revenus sur la plus grande partie de la distribution, et il est légèrement dégressif aux extrémités ; les taxes sur la consommation pèsent davantage sur les modestes.", 'c_insee_redis_2023', '2019', 'France', "Tous prélèvements confondus, le système est à peu près proportionnel, pas fortement progressif.", 'estimation', '55 %'),
  fait("Selon l'Institut des politiques publiques, le taux d'imposition effectif passe de 46 % pour les 0,1 % les plus riches à 26 % pour les milliardaires, dont l'essentiel du revenu reste dans leurs sociétés.", 'c_ipp_milliardaires_2023', '2016', 'France', "Au tout sommet, l'impôt devient dégressif.", 'estimation', '26 %'),
  fait("Les 10 % les plus riches ont déclaré 62 700 euros de revenus par personne en 2023 et payé en moyenne 17,5 % d'impôt sur le revenu ; le 1 % le plus riche finance un tiers de cet impôt.", 'c_obsineg_ir_2025', '2023', 'France', "Les plus aisés contribuent fortement à cet impôt, parce qu'ils concentrent une grande part des revenus.", 'etabli', '17,5 %'),
 ],
 court="Oui, les 10 % les plus aisés paient environ les trois quarts de l'impôt sur le revenu. Mais cet impôt ne pèse qu'environ 7 % des impôts. La TVA et la CSG, tout le monde les paie. Et au tout sommet, les milliardaires paient proportionnellement moins que les très riches.",
 moyen="Le chiffre est juste : selon la DGFiP, les 10 % des foyers les plus aisés paient 76 % de l'impôt sur le revenu. C'est logique, car cet impôt est progressif et ces foyers concentrent une grande part des revenus.\n\nMais l'impôt sur le revenu ne représente qu'environ 7 % des impôts et taxes. La TVA rapporte plus du double et la CSG environ 150 milliards : tout le monde les paie, y compris les foyers « non imposables ». Tous prélèvements confondus, l'Insee trouve un taux à peu près plat, autour de 55 % des revenus. Et l'IPP montre qu'au tout sommet, les milliardaires paient 26 %, contre 46 % pour les 0,1 % les plus riches.",
 detaille="Partons du fait. Selon la DGFiP, les 10 % des foyers les plus aisés acquittent 76 % de l'impôt sur le revenu net, et selon l'Observatoire des inégalités le 1 % le plus riche en paie un tiers. Ces foyers ont déclaré en moyenne 62 700 euros par personne en 2023 et payé 17,5 % d'impôt sur le revenu.\n\nMais regarder un seul impôt trompe. L'impôt sur le revenu rapporte environ 90 milliards, soit 7 % des quelque 1 200 milliards d'impôts et taxes. La TVA rapporte plus du double et la CSG environ 150 milliards. Ces prélèvements sont proportionnels, voire plus lourds pour les modestes dans le cas de la consommation. Résultat, selon l'Insee : l'ensemble des prélèvements tourne autour de 55 % des revenus pour la plupart des ménages, et devient légèrement dégressif aux extrémités, notamment parce que les plus aisés épargnent davantage.\n\nAu tout sommet, l'Institut des politiques publiques a mesuré que le taux effectif tombe de 46 % pour les 0,1 % les plus riches à 26 % pour les milliardaires : leurs revenus restent dans des sociétés et échappent à l'impôt sur le revenu. Dire que « les riches paient déjà tout » mélange donc un impôt et l'ensemble du système. La vraie question est celle du taux payé par rapport aux revenus et au patrimoine.",
 empathie="Beaucoup de gens entendent que la moitié des foyers ne paient pas d'impôt sur le revenu et se sentent seuls à payer. C'est compréhensible, mais tout le monde paie la TVA et la CSG.",
 legitimes=["L'impôt sur le revenu est effectivement très concentré sur les foyers aisés.", "Les plus aisés paient en montant beaucoup plus que les autres, ce qui est le principe d'un impôt progressif."],
 contre=[
  ("Plus de la moitié des Français ne paient pas d'impôt.", "Ils ne paient pas l'impôt sur le revenu, mais ils paient la TVA et la CSG, qui rapportent bien davantage."),
  ("Si on taxe plus les riches, ils partiront.", "Le constat de l'IPP porte sur le taux payé au sommet : il est plus bas que celui des simples très hauts revenus. On peut corriger cette anomalie en visant les revenus laissés dans les sociétés."),
 ],
 questions=["Savais-tu que l'impôt sur le revenu ne pèse qu'environ 7 % de tous les impôts ?", "Trouves-tu normal qu'un milliardaire paie un taux plus bas qu'un cadre très aisé ?"],
 limites=["La part de 76 % vient d'un article citant le bulletin DGFiP Statistiques n° 32 ; le bulletin lui-même n'a pas pu être ouvert, et la page Vie publique sur l'impôt sur le revenu non plus.", "L'étude de l'Insee porte sur 2019 et celle de l'IPP sur 2016, avant la suppression de l'ISF.", "Le taux de 55 % de l'Insee inclut les cotisations sociales, qui ouvrent des droits (retraite, chômage)."],
 publics={'convaincus': "Tu as raison sur un point : l'impôt sur le revenu est payé surtout par les plus aisés. Mais c'est environ 7 % des impôts ; la TVA et la CSG, ta famille les paie à chaque achat et sur chaque salaire. Et les milliardaires paient en proportion moins que les très hauts salaires, selon l'IPP.",
  'indecis': "Le chiffre circule et il est juste pour l'impôt sur le revenu. Pour juger, il faut regarder tous les prélèvements : l'Insee trouve un taux à peu près plat, autour de 55 % des revenus. Ce n'est donc pas « tout sur les riches », et au sommet le taux baisse même."},
 a_actualiser='2027-06-30', raison="Nouveau bulletin DGFiP sur l'impôt sur le revenu et nouvelles études sur les très hauts patrimoines.",
))

