FICHES.append(fiche(
 id='intermittents-spectacle-assistes', affirmation="Les intermittents du spectacle sont des assistés payés par nos impôts.", volet='social', sous_theme='Chômage',
 mots_cles=['intermittents du spectacle', 'intermittents assistes', 'regime des intermittents', 'annexes 8 et 10', 'intermittence', 'chomage des artistes', '507 heures', 'intermittents nos impots'],
 verdict='trompeur', fiabilite='etabli',
 resume="Les intermittents sont indemnisés par l'assurance chômage, financée surtout par des cotisations sur les salaires et, depuis 2019, par une fraction de CSG ; ce n'est pas le budget de l'État. Pour être indemnisé, il faut avoir travaillé au moins 507 heures en un an. Le régime coûte bien plus qu'il ne rapporte (1,89 Md€ de dépenses pour 472 M€ de contributions en 2025) : c'est une solidarité réelle entre salariés, assumée pour des métiers faits de contrats courts, dans un secteur culturel qui pèse 2 % de l'économie.",
 contexte="Le régime des intermittents revient régulièrement dans les débats sur le déficit de l'assurance chômage et sur le financement de la culture.",
 explication="Il faut distinguer qui finance (cotisations, CSG ou impôt d'État), ce que coûte le régime, et à quoi il sert pour des métiers où l'emploi est fait de contrats de quelques jours.",
 sources=[C_UNEDIC_INTERMITTENTS_2026, C_UNEDIC_FINANCEMENT, C_UNEDIC_INDEMNISATION_2022, C_FT_INTERMITTENTS_2025, C_DEPS_CULTURE_2025],
 faits=[
  fait("L'assurance chômage est financée principalement par la cotisation patronale de 4 % des salaires (44 Md€ en 2024) et, depuis 2019, par une fraction de la CSG activité ; les intermittents paient en plus une cotisation salariale de 2,4 %.", 'c_unedic_financement', '2024', 'France', "Ce sont surtout des cotisations, avec une part de CSG, et non le budget de l'État.", 'etabli', '44 Md€'),
  fait("Pour être indemnisé, un intermittent doit avoir travaillé au moins 507 heures dans les métiers du spectacle au cours des 12 derniers mois.", 'c_unedic_indemnisation_2022', '2022', 'France', "L'indemnisation suppose un travail régulier : ce n'est pas un revenu sans activité.", 'etabli', '507 heures'),
  fait("En 2024, près de 305 000 personnes ont travaillé comme intermittents du spectacle, pour 424 heures en moyenne par salarié.", 'c_ft_intermittents_2025', '2024', 'France', "Beaucoup d'intermittents travaillent sans atteindre le seuil d'indemnisation.", 'etabli', '305 000'),
  fait("En 2025, environ 126 500 intermittents étaient indemnisés en moyenne chaque mois, pour une dépense moyenne de 13 410 euros brut par allocataire sur l'année.", 'c_unedic_intermittents_2026', '2025', 'France', "Les montants versés restent modestes par personne.", 'etabli', '126 500'),
  fait("En 2025, les dépenses d'indemnisation des intermittents atteignent environ 1,89 Md€, pour 472 M€ de contributions, malgré un taux de cotisation total de 11,4 %.", 'c_unedic_intermittents_2026', '2025', 'France', "Le régime est structurellement déficitaire : c'est un fait défavorable, financé par la solidarité des autres cotisants.", 'etabli', '1,89 Md€'),
  fait("Les branches culturelles produisent 49,5 milliards d'euros de valeur ajoutée en 2023, soit 2,0 % de l'économie ; le spectacle vivant est la deuxième branche après l'audiovisuel.", 'c_deps_culture_2025', '2023', 'France', "Le secteur qui emploie les intermittents crée une richesse importante.", 'etabli', '49,5 milliards'),
 ],
 court="Les intermittents sont indemnisés par l'assurance chômage, financée surtout par des cotisations, pas par le budget de l'État. Il faut avoir travaillé 507 heures dans l'année. Le régime coûte plus qu'il ne rapporte : c'est une solidarité entre salariés, au service d'un secteur qui pèse 2 % de l'économie.",
 moyen="D'abord, qui paie ? L'assurance chômage est financée surtout par la cotisation patronale sur les salaires, et depuis 2019 par une part de CSG. Les intermittents et leurs employeurs cotisent même davantage que les autres salariés : 11,4 % au total.\n\nEnsuite, l'indemnisation suppose du travail : au moins 507 heures en un an. En 2024, près de 305 000 personnes ont travaillé comme intermittents, et environ 126 500 étaient indemnisées en moyenne chaque mois en 2025. Le régime est déficitaire, il faut le dire : 1,89 Md€ de dépenses pour 472 M€ de contributions. C'est un choix de solidarité pour des métiers faits de contrats courts, dans un secteur culturel qui produit 49,5 milliards de valeur ajoutée.",
 detaille="Le mot « assisté » ne correspond pas aux règles. Pour être indemnisé, un intermittent doit avoir travaillé au moins 507 heures dans le spectacle au cours des douze derniers mois. Or, selon France Travail, les près de 305 000 intermittents de 2024 ont travaillé en moyenne 424 heures : beaucoup n'atteignent pas le seuil. En 2025, environ 126 500 étaient indemnisés chaque mois, pour une dépense moyenne de 13 410 euros brut sur l'année.\n\nCe ne sont pas « nos impôts » au sens du budget de l'État. L'assurance chômage est financée surtout par les cotisations patronales (44 Md€ en 2024) et, depuis 2019, par une fraction de la CSG, qui a remplacé la cotisation des salariés. Les intermittents, eux, gardent une cotisation salariale de 2,4 %, et le taux total sur leurs salaires atteint 11,4 %.\n\nLe régime n'est pas à l'équilibre : en 2025, 1,89 Md€ de dépenses pour 472 M€ de contributions. Cet écart est financé par l'ensemble des cotisants. C'est un choix ancien, né en 1936 pour le cinéma, qui permet à des techniciens et des artistes de vivre entre deux contrats de quelques jours. Sans lui, festivals, tournages et spectacles dépendraient d'une main-d'œuvre encore plus précaire, dans un secteur qui pèse 2 % de l'économie.",
 empathie="Il peut sembler injuste que certains touchent le chômage entre deux contrats quand d'autres n'y ont pas droit. Cette impression mérite une réponse précise sur les règles et sur qui paie.",
 legitimes=["Le régime des intermittents est déficitaire et financé en partie par les autres cotisants.", "Certains employeurs peuvent abuser des contrats courts en comptant sur l'indemnisation."],
 contre=[
  ("Ils touchent le chômage sans travailler.", "Il faut au moins 507 heures de travail dans l'année ; beaucoup d'intermittents n'atteignent pas ce seuil et ne sont pas indemnisés."),
  ("Leur régime creuse le déficit de l'assurance chômage.", "C'est vrai que les dépenses dépassent nettement les contributions ; c'est une solidarité assumée pour des métiers à contrats courts, qui peut se débattre sans parler d'assistanat."),
 ],
 questions=["Savais-tu qu'il faut 507 heures de travail par an pour être indemnisé ?", "Comment payer un technicien de festival entre deux contrats de quelques jours, sinon ?"],
 limites=["La CSG est un impôt : depuis 2019, une partie de l'indemnisation est donc financée par un prélèvement fiscal affecté ; sa part exacte n'a pas été trouvée dans une source lue.", "Aucun rapport récent de la Cour des comptes sur les intermittents n'a été lu.", "Le nombre de salariés intermittents (2024) et celui des indemnisés (2025) ne portent pas sur la même année."],
 publics={'convaincus': "Je comprends que ça agace de voir un régime à part. Mais pour toucher le chômage, un intermittent doit avoir travaillé au moins 507 heures dans l'année, et ce sont surtout des cotisations sur les salaires qui paient, pas le budget de l'État. Le régime est déficitaire, c'est vrai : c'est une solidarité entre salariés, pas de l'assistanat.",
  'indecis': "Le régime coûte plus qu'il ne rapporte, et c'est un vrai débat. Mais il concerne des gens qui travaillent, par contrats très courts, dans un secteur qui produit 2 % de la richesse du pays. La question est de savoir comment le financer, pas de traiter ces travailleurs d'assistés."},
 a_actualiser='2027-09-30', raison="Nouvelle publication annuelle de l'Unédic sur les annexes 8 et 10.",
))

