# 1 ── L'OTAN a-t-elle provoqué la guerre en Ukraine ? ─────────────────────────
D_OTAN_BUCAREST_2008 = ('d_otan_bucarest_2008', src("NATO decisions on open-door policy (sommet de Bucarest)", "OTAN (NATO Update)", "3 avril 2008",
  "https://www.nato.int/docu/update/2008/04-april/e0403c.html",
  "Au sommet de Bucarest, les Alliés « agreed that these countries will become members of NATO » (Ukraine et Géorgie) et « made clear that they support Georgia's and Ukraine's applications for MAP ». Le plan d'action pour l'adhésion (MAP) n'est pas accordé : des questions restent ouvertes et les ministres doivent faire le point en décembre 2008.",
  "Texte officiel de l'Alliance ; montre à la fois la promesse de principe et le refus d'engager concrètement l'adhésion.", 'primaire'))
D_BROOKINGS_SCHOLZ_2022 = ('d_brookings_scholz_2022', src("Scholz holds his ground in Putin's den", "Brookings Institution (Constanze Stelzenmüller)", "16 février 2022",
  "https://www.brookings.edu/articles/scholz-holds-his-ground-in-putins-den",
  "En conférence de presse à Moscou, le chancelier allemand Olaf Scholz dit de l'adhésion de l'Ukraine à l'OTAN : « That is not an issue we will likely encounter while we are in office » (ce n'est pas une question qui se posera probablement pendant notre mandat), en ajoutant qu'il ne savait pas combien de temps le président russe comptait rester au pouvoir.",
  "Think tank américain de référence (centriste) ; rapporte une déclaration publique faite neuf jours avant l'invasion.", 'secondaire'))
D_ALJAZEERA_CANDIDATURE_2022 = ('d_aljazeera_candidature_2022', src("Ukraine accelerates bid to join NATO after Russia's annexation", "Al Jazeera", "30 septembre 2022",
  "https://www.aljazeera.com/news/2022/9/30/ukraine-accelerates-bid-to-join-nato-after-russias-annexation",
  "Volodymyr Zelensky annonce : « We are taking our decisive step by signing Ukraine's application for accelerated accession to NATO ». Le secrétaire général Jens Stoltenberg reste prudent : « Our focus now is on providing immediate support to Ukraine ». L'adhésion exige l'unanimité des membres.",
  "Média international ; date la demande formelle d'adhésion, sept mois après l'invasion.", 'secondaire'))
D_GC_POUTINE_2022 = ('d_gc_poutine_2022', src("Comment Poutine veut effacer l'Ukraine (traduction commentée du discours du 21 février 2022)", "Le Grand Continent", "23 février 2022",
  "https://legrandcontinent.eu/fr/2022/02/23/comment-poutine-veut-effacer-lukraine/",
  "Dans son discours du 21 février 2022, Vladimir Poutine affirme que « l'Ukraine moderne a été entièrement créée par la Russie, ou pour être plus précis par la Russie bolchévique, communiste » et dit de Lénine : « Il en a été le créateur et l'architecte ». Il invoque aussi l'OTAN : « L'Ukraine abrite des missions d'entraînement de l'OTAN qui sont, en fait, des bases militaires étrangères. »",
  "Revue européenne de géopolitique ; traduction intégrale d'une source primaire (discours du Kremlin).", 'primaire'))
D_CERI_COLAS_2022 = ('d_ceri_colas_2022', src("Lénine est-il « l'auteur et l'architecte » de l'Ukraine comme le dit Poutine ?", "Sciences Po, CERI (Dominique Colas)", "16 juin 2022",
  "https://www.sciencespo.fr/ceri/fr/content/dossiersduceri/lenine-est-il-l-auteur-et-l-architecte-de-l-ukraine-comme-le-dit-poutine.html",
  "L'historien examine la thèse du discours du 21 février 2022 selon laquelle Lénine serait « l'auteur et l'architecte » de l'Ukraine. Il rappelle que « Lénine a appuyé les revendications ukrainiennes en faveur de l'indépendance avant la guerre de 1914 » et conclut que Poutine « n'est pas fondé » à faire de Lénine le créateur de l'Ukraine.",
  "Centre de recherche universitaire (Sciences Po).", 'etude'))
D_SEAE_ONU_2022 = ('d_seae_onu_2022', src("UN General Assembly demands Russian Federation withdraw all military forces from the territory of Ukraine", "Service européen pour l'action extérieure (SEAE)", "2 mars 2022",
  "https://www.eeas.europa.eu/eeas/un-general-assembly-demands-russian-federation-withdraw-all-military-forces-territory-ukraine_und_cs",
  "L'Assemblée générale de l'ONU adopte la résolution par 141 voix pour et 5 contre (Russie, Biélorussie, Corée du Nord, Érythrée, Syrie). Elle « deplores in the strongest terms » l'agression russe et exige que la Russie retire immédiatement ses forces.",
  "Service diplomatique de l'UE, qui rend compte d'un vote de l'ONU ; le nombre d'abstentions n'y figure pas.", 'secondaire'))
D_RUBICON_HAROCHE_2023 = ('d_rubicon_haroche_2023', src("Vous avez dit sphères d'influence ? Le néoréalisme face à la guerre russo-ukrainienne", "Le Rubicon (Pierre Haroche, Queen Mary University of London)", "16 février 2023",
  "https://lerubicon.org/vous-avez-dit-spheres-dinfluence-le-neorealisme-face-a-la-guerre-russo-ukrainienne/fulltext.pdf",
  "L'auteur présente la thèse de John Mearsheimer et Stephen Walt : l'élargissement de l'OTAN et la coopération avec l'Ukraine auraient empiété sur la sphère d'influence russe et poussé Moscou à réagir. Il la discute : le fait que la Russie se sente menacée ne dit pas pourquoi elle agit ainsi ; selon la théorie de l'équilibre de la menace, l'élargissement vers l'Est s'explique très bien par la menace russe ; plus de retenue occidentale n'aurait pas nécessairement rendu la Russie moins agressive.",
  "Revue académique de relations internationales ; article d'analyse théorique signé.", 'etude'))

FICHES.append(fiche(
 id='otan-provoque-guerre-ukraine', affirmation="C'est l'OTAN qui a provoqué la guerre en Ukraine.", volet='international', sous_theme='Guerres et conflits',
 mots_cles=['otan guerre ukraine', 'otan a provoque', 'expansion de l otan', 'elargissement otan', 'mearsheimer', 'bucarest 2008', 'provocation occidentale', 'guerre en ukraine responsable'],
 verdict='trompeur', fiabilite='interpretation',
 resume="En 2008, l'OTAN a promis que l'Ukraine deviendrait membre un jour, mais a refusé de lancer son adhésion. En février 2022, aucune adhésion n'était à l'ordre du jour : le chancelier allemand le disait à Moscou même. Le 21 février 2022, Poutine justifiait l'invasion autant par la négation de l'Ukraine comme nation que par l'OTAN. L'élargissement de l'Alliance fait partie du contexte et nourrit un vrai débat entre chercheurs ; mais la décision d'envahir a été prise à Moscou, et l'Assemblée générale de l'ONU l'a condamnée comme une agression.",
 contexte="Cette idée circule à l'extrême droite comme dans une partie de la gauche : elle sert à renvoyer la responsabilité de la guerre sur les États-Unis et l'OTAN.",
 explication="Il faut distinguer trois choses : ce que l'OTAN a réellement promis et fait, ce que le Kremlin a dit de ses propres buts, et le débat académique sur le rôle de l'élargissement dans la montée des tensions.",
 sources=[D_OTAN_BUCAREST_2008, D_BROOKINGS_SCHOLZ_2022, D_ALJAZEERA_CANDIDATURE_2022, D_GC_POUTINE_2022, D_CERI_COLAS_2022, D_SEAE_ONU_2022, D_RUBICON_HAROCHE_2023],
 faits=[
  fait("Au sommet de Bucarest (avril 2008), l'OTAN déclare que l'Ukraine et la Géorgie deviendront membres, mais ne leur accorde pas le plan d'action pour l'adhésion.", 'd_otan_bucarest_2008', '2008', 'OTAN', "La promesse de principe a existé et Moscou l'a perçue comme une menace ; mais l'adhésion concrète a été refusée.", 'etabli'),
  fait("Le 15 février 2022, à Moscou, Olaf Scholz déclare que l'adhésion de l'Ukraine ne se posera probablement pas pendant son mandat.", 'd_brookings_scholz_2022', '2022', 'Allemagne, Russie', "À la veille de l'invasion, aucune adhésion n'était en préparation.", 'etabli'),
  fait("L'Ukraine n'a signé sa demande d'adhésion accélérée à l'OTAN que le 30 septembre 2022, sept mois après l'invasion, et le secrétaire général de l'OTAN est resté prudent.", 'd_aljazeera_candidature_2022', '2022', 'Ukraine', "La candidature formelle est une conséquence de la guerre, pas sa cause.", 'etabli'),
  fait("Dans son discours du 21 février 2022, Vladimir Poutine affirme que l'Ukraine moderne a été « entièrement créée » par la Russie bolchévique ; il présente aussi les missions d'entraînement de l'OTAN comme des bases étrangères.", 'd_gc_poutine_2022', '2022', 'Russie', "Le Kremlin invoque l'OTAN, mais aussi la négation de l'Ukraine comme nation : l'OTAN n'est qu'une partie de son récit.", 'etabli'),
  fait("Le 2 mars 2022, l'Assemblée générale de l'ONU déplore l'agression russe et exige le retrait des troupes, par 141 voix contre 5.", 'd_seae_onu_2022', '2022', 'Monde', "Une très large majorité des États, bien au-delà de l'OTAN, a qualifié la guerre d'agression.", 'etabli', '141 voix'),
  fait("Des chercheurs réalistes comme John Mearsheimer imputent la guerre à l'élargissement de l'OTAN ; d'autres, comme Pierre Haroche, répondent que cet élargissement s'explique par la menace russe et qu'une retenue occidentale n'aurait pas garanti la paix.", 'd_rubicon_haroche_2023', '2023', 'Débat académique', "La thèse de la provocation est défendue par des universitaires sérieux : c'est un débat réel, qu'il faut présenter honnêtement.", 'debat'),
 ],
 court="L'OTAN a promis en 2008 que l'Ukraine la rejoindrait un jour, sans jamais lancer l'adhésion ; en 2022, elle n'était pas à l'ordre du jour. Poutine a justifié l'invasion en niant l'existence même de l'Ukraine. L'élargissement fait partie du contexte, mais c'est Moscou qui a choisi la guerre.",
 moyen="Il y a un fond de vérité : en 2008, à Bucarest, l'OTAN a déclaré que l'Ukraine deviendrait membre, et Moscou l'a vécu comme une menace. Des chercheurs comme John Mearsheimer en font la cause principale de la guerre.\n\nMais l'Alliance a refusé de lancer l'adhésion, et en février 2022 le chancelier allemand disait à Moscou qu'elle ne se poserait probablement pas pendant son mandat. L'Ukraine n'a demandé son adhésion qu'en septembre 2022, après l'invasion. Et le 21 février 2022, Poutine affirmait que l'Ukraine moderne avait été créée par la Russie bolchévique. Une très large majorité des pays de l'ONU a condamné une agression : on peut critiquer l'OTAN sans absoudre l'agresseur.",
 detaille="Commençons par l'OTAN. En avril 2008, au sommet de Bucarest, les Alliés ont déclaré que l'Ukraine et la Géorgie deviendraient membres, mais leur ont refusé le plan d'action pour l'adhésion. Cette promesse floue a nourri l'inquiétude de Moscou sans rien garantir à Kiev. En février 2022, Olaf Scholz disait à Moscou que l'adhésion ne se poserait probablement pas pendant son mandat. L'Ukraine n'a signé sa demande d'adhésion accélérée que le 30 septembre 2022, sept mois après l'invasion.\n\nRegardons ensuite ce que dit le Kremlin. Dans son discours du 21 février 2022, Vladimir Poutine affirme que l'Ukraine moderne a été « entièrement créée » par la Russie bolchévique et que Lénine en fut « l'architecte ». Il parle aussi de l'OTAN. Mais nier l'existence d'une nation ne relève pas d'une simple inquiétude sécuritaire. L'historien Dominique Colas (Sciences Po) rappelle que cette lecture de Lénine n'est pas fondée.\n\nLe débat académique existe. John Mearsheimer et Stephen Walt voient dans l'élargissement de l'OTAN la cause de la guerre. D'autres chercheurs, comme Pierre Haroche, répondent que l'élargissement s'explique par la menace russe et qu'une retenue occidentale n'aurait pas garanti la paix. Quelle que soit la place qu'on donne à l'OTAN dans la montée des tensions, la décision d'envahir a été prise à Moscou. Le 2 mars 2022, l'Assemblée générale de l'ONU l'a condamnée par 141 voix contre 5.",
 empathie="Beaucoup de gens se méfient à juste titre des guerres menées au nom de l'Occident, de l'Irak à la Libye. Cette méfiance est saine ; elle doit simplement s'appliquer aussi à la propagande du Kremlin.",
 legitimes=["La promesse de Bucarest en 2008 était floue et a été perçue comme une menace à Moscou.", "Des chercheurs reconnus défendent la thèse d'une responsabilité de l'élargissement de l'OTAN.", "Les États-Unis ont eux-mêmes mené des guerres d'agression, comme en Irak."],
 contre=[
  ("L'OTAN s'est étendue jusqu'aux frontières de la Russie, c'est une provocation.", "Des pays d'Europe de l'Est ont demandé à entrer dans l'OTAN par peur de la Russie ; et l'adhésion de l'Ukraine n'était pas à l'ordre du jour en 2022, de l'aveu même des Européens."),
  ("Mearsheimer, un grand universitaire américain, dit que c'est la faute de l'OTAN.", "Sa thèse est sérieuse et discutée, mais contestée par d'autres chercheurs ; et elle ne change rien au fait qu'envahir un pays souverain est une agression condamnée par l'ONU."),
 ],
 questions=["Savais-tu que l'Ukraine n'a demandé à entrer dans l'OTAN qu'après l'invasion ?", "Si l'enjeu était seulement l'OTAN, pourquoi Poutine expliquait-il que l'Ukraine était une création de la Russie ?"],
 limites=["Le discours de Poutine a été lu dans la traduction du Grand Continent, pas dans la version originale du Kremlin.", "Le texte de Mearsheimer lui-même n'a pas été lu : sa thèse est présentée à travers l'article de Pierre Haroche.", "La page du SEAE ne donne pas le nombre d'abstentions au vote de l'ONU.", "Les demandes russes de décembre 2021 (traités sur la sécurité) n'ont pas été vérifiées dans une source lue."],
 publics={'convaincus': "Tu as raison sur un point : en 2008, l'OTAN a promis à l'Ukraine une adhésion future, et Moscou l'a mal pris. Mais en 2022, personne ne préparait cette adhésion, et l'Ukraine ne l'a demandée qu'après l'invasion. Le 21 février 2022, Poutine expliquait que l'Ukraine était une création de la Russie : ce n'est pas un discours de défense, c'est un discours de conquête.",
  'indecis': "La question est légitime, et des chercheurs sérieux en débattent. Les faits datés aident à y voir clair : promesse floue en 2008, aucune adhésion prévue en 2022, demande ukrainienne seulement après l'invasion. Une très large majorité des pays de l'ONU, pas seulement l'Occident, a parlé d'agression."},
 a_actualiser='2027-06-30', raison="Évolution des négociations de paix et des garanties de sécurité pour l'Ukraine.",
))

