FICHES.append(fiche(
 id='russie-valeurs-chretiennes', affirmation="La Russie de Poutine défend les valeurs chrétiennes de l'Europe.", volet='international', sous_theme='Russie',
 mots_cles=['russie valeurs chretiennes', 'poutine chretien', 'poutine defend la chretiente', 'russie rempart', 'patriarche kirill', 'russie traditionnelle', 'valeurs traditionnelles russie', 'eglise orthodoxe russe'],
 verdict='trompeur', fiabilite='interpretation',
 resume="Le pouvoir russe s'appuie sur l'Église orthodoxe et adopte des lois conservatrices : contre les personnes LGBT, contre l'accès à l'avortement. Mais la pratique religieuse reste faible : selon le Pew Research Center, seuls 6 % des orthodoxes russes vont à l'église chaque semaine. Le patriarche Kirill a béni la guerre au point de dire que la mort au combat « lave tous les péchés », ce que le pape François et des théologiens orthodoxes ont dénoncé. Et la Russie persécute des chrétiens : les Témoins de Jéhovah sont interdits depuis 2017. Le « christianisme » du Kremlin est surtout un drapeau politique.",
 contexte="Une partie de l'extrême droite européenne présente Vladimir Poutine comme le dernier défenseur de la civilisation chrétienne face à un Occident « décadent ».",
 explication="Il faut distinguer la religion comme pratique et comme morale, et la religion comme outil de pouvoir. On regarde donc la pratique réelle, les positions des Églises elles-mêmes et le traitement des croyants minoritaires.",
 sources=[D_PEW_RUSSIE_2017, D_AP_KIRILL_2022, D_ALETEIA_PAPE_2022, D_NOVAYA_TJ_2022, D_FIDH_RUSSIE_2024],
 faits=[
  fait("En Russie, la part des personnes se déclarant orthodoxes est passée de 37 % en 1991 à 71 %, mais seuls 6 % des orthodoxes russes vont à l'église au moins une fois par semaine.", 'd_pew_russie_2017', 'avant 2017', 'Russie', "L'orthodoxie est surtout une identité nationale, peu une pratique.", 'etabli', '6 %'),
  fait("Le 25 septembre 2022, le patriarche Kirill déclare que le sacrifice d'un soldat mort en Ukraine « lave tous les péchés » ; un prêtre orthodoxe y voit l'idée d'un « terrorisme religieux ».", 'd_ap_kirill_2022', '2022', 'Russie', "La hiérarchie orthodoxe russe sacralise une guerre d'agression, contre la tradition chrétienne du martyre.", 'etabli'),
  fait("En mai 2022, le pape François déclare que « le patriarche ne peut pas devenir l'enfant de chœur de Poutine », après un entretien où Kirill lui avait lu les justifications de la guerre.", 'd_aleteia_pape_2022', '2022', 'Vatican, Russie', "Le chef de la plus grande Église chrétienne désavoue l'usage religieux de la guerre.", 'etabli'),
  fait("En 2022, la Cour européenne des droits de l'homme a jugé illégale l'interdiction des Témoins de Jéhovah, déclarés « extrémistes » en 2017, et condamné la Russie à verser plus de 63 millions d'euros.", 'd_novaya_tj_2022', '2017-2022', 'Russie', "Le régime persécute des chrétiens qui ne relèvent pas de l'Église officielle.", 'etabli', '63 millions d’euros'),
  fait("Avec le soutien de l'Église orthodoxe, la Douma a dépénalisé en 2017 les violences domestiques sans hospitalisation ; la Russie a ensuite interdit toute « propagande LGBT » (2022) et restreint l'accès à l'avortement.", 'd_fidh_russie_2024', '2012-2024', 'Russie', "Le régime adopte bien des lois conservatrices, que certains chrétiens approuvent : c'est le cœur de son attrait. Mais elles reposent sur la répression, pas sur la charité.", 'etabli'),
 ],
 court="Le Kremlin se drape dans l'orthodoxie, mais seuls 6 % des orthodoxes russes vont à l'église chaque semaine. Le patriarche Kirill a béni la guerre, ce que le pape a dénoncé. Et la Russie persécute des chrétiens comme les Témoins de Jéhovah. C'est un drapeau politique, pas une défense de la foi.",
 moyen="Le pouvoir russe s'affiche avec l'Église orthodoxe et vote des lois conservatrices, contre les personnes LGBT ou contre l'accès à l'avortement. C'est ce qui séduit une partie de la droite européenne.\n\nMais regardons de près. Selon le Pew Research Center, la grande majorité des Russes se disent orthodoxes, mais seuls 6 % des orthodoxes vont à l'église chaque semaine. Le patriarche Kirill a affirmé que mourir en Ukraine « lave tous les péchés », et le pape François lui a répondu qu'il ne pouvait pas devenir « l'enfant de chœur de Poutine ». La Russie a interdit les Témoins de Jéhovah et la Cour européenne des droits de l'homme l'a condamnée. Une religion d'État au service d'une guerre, ce n'est pas l'Évangile.",
 detaille="Le régime russe a fait de l'orthodoxie un pilier de son identité. La part des Russes qui se disent orthodoxes est passée de 37 % en 1991 à 71 %, selon le Pew Research Center. Mais seuls 6 % de ces orthodoxes vont à l'église au moins une fois par semaine. L'appartenance est nationale plus que religieuse.\n\nL'Église officielle s'est mise au service de la guerre. Le 25 septembre 2022, le patriarche Kirill a déclaré que le sacrifice d'un soldat mort en Ukraine « lave tous les péchés ». Des théologiens orthodoxes y voient une trahison de l'idée chrétienne de martyre. Le pape François a déclaré que le patriarche ne pouvait pas devenir « l'enfant de chœur de Poutine ». De nombreux prêtres ukrainiens ont cessé de prier pour Kirill.\n\nLes lois « traditionnelles » existent : dépénalisation en 2017 des violences domestiques sans hospitalisation, avec le soutien de l'Église ; interdiction de toute « propagande LGBT » ; restrictions sur l'avortement. Mais elles s'accompagnent de répression religieuse. Les Témoins de Jéhovah, des chrétiens, sont interdits depuis 2017 comme « extrémistes » ; la Cour européenne des droits de l'homme a jugé cette interdiction illégale et condamné la Russie à verser plus de 63 millions d'euros. Défendre des valeurs chrétiennes, ce serait d'abord protéger la liberté de conscience et la vie des civils.",
 empathie="On peut être attaché à la foi chrétienne et inquiet de la place qu'elle occupe aujourd'hui en Europe. C'est justement pour cela qu'il vaut la peine de regarder ce que le Kremlin fait réellement des croyants.",
 legitimes=["Le pouvoir russe a réellement adopté des lois conservatrices sur la famille, la sexualité et l'avortement.", "L'Église orthodoxe a retrouvé une place centrale en Russie après l'époque soviétique."],
 contre=[
  ("Au moins la Russie protège la famille traditionnelle.", "Elle a dépénalisé une partie des violences domestiques en 2017 : protéger la famille, c'est d'abord protéger les femmes et les enfants des coups."),
  ("Le patriarche Kirill est un chef chrétien, il sait ce qu'il dit.", "Le pape et des théologiens orthodoxes ont dénoncé sa bénédiction de la guerre ; et de nombreux prêtres ukrainiens, orthodoxes eux aussi, ont rompu avec lui."),
 ],
 questions=["Savais-tu que la Russie interdit les Témoins de Jéhovah, qui sont des chrétiens ?", "Pour toi, un chef religieux qui dit que mourir à la guerre efface tous les péchés défend-il l'Évangile ?"],
 limites=["Les chiffres de pratique religieuse du Pew Research Center datent d'une enquête publiée en 2017.", "Les taux d'avortement et de divorce en Russie (Rosstat) n'ont pas été trouvés dans une source lue ; ils ne sont pas cités.", "La prise de position du Conseil œcuménique des Églises n'a pas été vérifiée.", "Les financements russes de l'extrême droite européenne sont traités dans la fiche rn-russie-liens."],
 publics={'convaincus': "Si Poutine défendait la foi, les églises seraient pleines : or seuls 6 % des orthodoxes russes y vont chaque semaine. Son patriarche dit que mourir en Ukraine efface tous les péchés, et le pape lui-même l'a désavoué. Et la Russie emprisonne des chrétiens qui ne pensent pas comme l'Église officielle.",
  'indecis': "C'est vrai, le pouvoir russe affiche des lois conservatrices et s'appuie sur l'Église. Mais la pratique religieuse y reste faible, l'Église officielle bénit la guerre et des chrétiens minoritaires sont persécutés. Le christianisme sert surtout de drapeau au régime."},
 a_actualiser='2027-11-11', raison="Nouvelles enquêtes sur la pratique religieuse et évolution des lois russes.",
))

# 3 ── Les eurodéputés RN travaillent-ils au Parlement européen ? ─────────────
D_PARISIEN_BARDELLA_2025 = ('d_parisien_bardella_2025', src("« C'est l'inconnu du Thalys » : Pourquoi Jordan Bardella est un « député fantôme » au Parlement européen", "Le Parisien (Clément Solal, avec Alexandre Sulzer)", "1er janvier 2025",
  "https://www.universitepopulairetoulouse.fr/IMG/pdf/le_parisien_.pdf",
  "Selon le décompte du journal, depuis juillet 2024 Jordan Bardella a manqué sept des neuf réunions officielles de la commission des affaires étrangères et huit des onze réunions de la Conférence des présidents ; son entourage conteste la notion d'absence. Il revendique « 94% d'assiduité aux votes » (plénière seulement) et dit avoir déposé 90 amendements. Le politologue Olivier Costa rappelle que les députés RN ont longtemps figuré parmi les moins actifs du classement des activités parlementaires, notamment pour les amendements.",
  "Presse de référence ; copie de l'article hébergée par un site tiers. Les chiffres d'amendements viennent de Jordan Bardella lui-même.", 'secondaire'))
D_FRANCE24_RN_PE_2024 = ('d_france24_rn_pe_2024', src("French far right's rhetoric at odds with its voting record at EU Parliament", "France 24 (Romain Brunet), traduit et reproduit par inkl", "2024 (avant les élections européennes)",
  "https://inkl.com/news/french-far-right-s-rhetoric-at-odds-with-its-voting-record-at-eu-parliament",
  "Le RN a diffusé un visuel revendiquant 93,95 % de présence aux sessions plénières de Strasbourg ; l'article juge ce chiffre trompeur car une grande partie du travail se fait en commission. Selon Complément d'enquête, entre juillet 2019 et décembre 2023, Jordan Bardella a manqué 70 % des réunions de sa commission.",
  "Média public international ; lu dans une reproduction en anglais, sans date de publication affichée.", 'secondaire'))
D_DELORS_PE_2025 = ('d_delors_pe_2025', src("Un an après les élections, un Parlement européen profondément instable", "Institut Jacques Delors (Isabelle Marchais)", "juillet 2025",
  "https://institutdelors.eu/content/uploads/2025/07/PB_250708_PE_un_an_apres_Marchais_FR.pdf",
  "Le RN compte 29 élus dans le groupe des Patriotes pour l'Europe (85 députés sur 720). Des élus d'extrême droite sont désormais plus actifs : ils s'appuient sur des collaborateurs expérimentés, « rédigent des rapports et des amendements » ; une partie reste toutefois en marge du travail parlementaire. Le cordon sanitaire les prive de présidences de commission, mais le groupe a obtenu des rapports (biotechnologies, financement des PME, objectifs climatiques pour 2040).",
  "Think tank pro-européen (orientation à signaler) ; analyse qualitative, sans chiffres par élu.", 'etude'))
D_PUBLICSENAT_CORDON_2024 = ('d_publicsenat_cordon_2024', src("Au Parlement européen, Jordan Bardella peine à se normaliser", "Public Sénat (Audrey Vuetaz)", "25 juillet 2024",
  "https://www.publicsenat.fr/actualites/politique/au-parlement-europeen-jordan-bardella-peine-a-se-normaliser",
  "Jordan Bardella, président des Patriotes pour l'Europe (84 membres), siège désormais à la commission des affaires étrangères, après la commission des pétitions. Fabrice Leggeri (RN) n'a pas obtenu la vice-présidence du Parlement, et Malika Sorel n'a pas été élue à la présidence de la commission de la culture : « Les Patriotes restent donc derrière le cordon. »",
  "Média parlementaire public.", 'secondaire'))
D_EUMATRIX_2024 = ('d_eumatrix_2024', src("Influence Index 2024: Overview by country", "EU Matrix", "2024 (avant les élections européennes)",
  "https://eumatrix.eu/en/blog/Influence-Index-2024-Overview-by-country",
  "« The overall influence of French MEPs in the European Parliament is in the lower ranks », notamment parce qu'environ un tiers de la délégation française appartient au groupe nationaliste ID, soumis à un « cordon sanitaire » qui l'écarte des postes de direction.",
  "Cabinet d'analyse indépendant du Parlement européen ; indice d'influence, pas d'activité.", 'etude'))

FICHES.append(fiche(
 id='rn-eurodeputes-travail', affirmation="Les eurodéputés RN ne travaillent pas au Parlement européen.", volet='politique', sous_theme='Rassemblement national',
 mots_cles=['eurodeputes rn', 'bardella parlement europeen', 'depute fantome', 'rn absent parlement europeen', 'rn ne travaille pas', 'assiduite eurodeputes', 'amendements rn', 'patriotes pour l europe'],
 verdict='plutot_exact', fiabilite='interpretation',
 resume="Pour la législature 2019-2024, la critique est largement fondée : selon le politologue Olivier Costa, les députés RN ont longtemps figuré parmi les moins actifs, et Jordan Bardella a manqué 70 % des réunions de sa commission selon Complément d'enquête. Le RN met en avant sa présence aux votes en plénière, mais l'essentiel du travail se fait en commission. Depuis 2024, le tableau évolue : selon l'Institut Delors, une partie des élus d'extrême droite rédige désormais rapports et amendements, même si d'autres restent en marge. « Ne travaillent pas » est donc trop absolu, mais le faible investissement est documenté.",
 contexte="Le RN est le premier parti français au Parlement européen et présente ses élus comme assidus ; ses adversaires les décrivent comme des « députés fantômes ». La question est distincte de l'affaire des assistants parlementaires.",
 explication="Il faut distinguer la présence aux votes en séance plénière, facile à afficher, et le travail en commission (rapports, amendements, négociations), qui fait la loi européenne. Et comparer la législature 2019-2024 à celle qui a commencé en 2024.",
 sources=[D_PARISIEN_BARDELLA_2025, D_FRANCE24_RN_PE_2024, D_DELORS_PE_2025, D_PUBLICSENAT_CORDON_2024, D_EUMATRIX_2024],
 faits=[
  fait("Selon le politologue Olivier Costa, les députés RN ont longtemps figuré parmi les moins actifs du classement des activités parlementaires, notamment pour le nombre d'amendements.", 'd_parisien_bardella_2025', '2019-2024', 'Parlement européen', "Le faible investissement législatif du RN est relevé par un spécialiste du Parlement.", 'interpretation'),
  fait("Le RN revendique 93,95 % de présence en plénière, mais selon Complément d'enquête, Jordan Bardella a manqué 70 % des réunions de sa commission entre juillet 2019 et décembre 2023.", 'd_france24_rn_pe_2024', '2019-2023', 'Parlement européen', "La présence aux votes ne dit rien du travail en commission, où s'écrivent les textes.", 'etabli', '70 %'),
  fait("Selon le décompte du Parisien, depuis juillet 2024 Jordan Bardella a manqué sept des neuf réunions de la commission des affaires étrangères ; il affirme de son côté avoir déposé 90 amendements, chiffre non vérifié.", 'd_parisien_bardella_2025', '2024', 'Parlement européen', "Le président du groupe reste peu présent en commission, mais revendique une activité écrite.", 'estimation'),
  fait("Selon l'Institut Delors, des élus d'extrême droite sont plus actifs depuis 2024 et rédigent des rapports et des amendements, même si une partie reste en marge ; leur groupe a obtenu des rapports sur les biotechnologies, les PME et le climat.", 'd_delors_pe_2025', '2024-2025', 'Parlement européen', "Fait défavorable à l'affirmation : l'implication s'est améliorée.", 'interpretation'),
  fait("Le cordon sanitaire prive les élus RN des présidences de commission et de la vice-présidence du Parlement ; selon EU Matrix, il place l'influence de la délégation française dans le bas du classement.", 'd_eumatrix_2024', '2019-2024', 'Parlement européen', "Le faible poids du RN tient aussi à son isolement politique, pas seulement à son assiduité.", 'etabli'),
 ],
 court="La critique visait juste pour 2019-2024 : Jordan Bardella a manqué 70 % des réunions de sa commission selon Complément d'enquête, et les élus RN figuraient parmi les moins actifs. Leur présence aux votes est élevée, mais la loi se fait en commission. Depuis 2024, une partie d'entre eux s'implique davantage.",
 moyen="Le RN met en avant sa présence aux votes en séance plénière. Mais l'essentiel du travail européen se fait en commission. Or, selon Complément d'enquête, Jordan Bardella a manqué 70 % des réunions de sa commission entre 2019 et 2023, et le politologue Olivier Costa rappelle que les députés RN figuraient parmi les moins actifs.\n\nIl faut être honnête : depuis 2024, selon l'Institut Delors, une partie des élus d'extrême droite rédige des rapports et des amendements. D'autres restent en marge, et le président du groupe reste peu présent en commission selon Le Parisien. « Ils ne font rien » est trop fort ; « ils ont longtemps peu travaillé » est documenté.",
 detaille="Le travail d'un eurodéputé se mesure de plusieurs façons. Le RN met en avant un taux de présence de 93,95 % en séance plénière, où l'on vote. Mais les textes s'écrivent en commission : on y négocie, on y dépose des amendements, on y rédige des rapports. Selon Complément d'enquête, Jordan Bardella a manqué 70 % des réunions de sa commission entre juillet 2019 et décembre 2023. Le politologue Olivier Costa rappelle que les députés RN ont longtemps figuré parmi les moins actifs, notamment pour les amendements.\n\nDepuis les élections de 2024, le tableau bouge. Selon l'Institut Jacques Delors, des élus d'extrême droite s'appuient sur des collaborateurs expérimentés, rédigent des rapports et des amendements, et leur groupe des Patriotes a obtenu des rapports sur les biotechnologies, les PME ou le climat. Une partie reste en marge. Selon le décompte du Parisien, Jordan Bardella a manqué sept des neuf réunions de la commission des affaires étrangères depuis juillet 2024 ; il affirme avoir déposé 90 amendements, chiffre qu'il avance lui-même.\n\nLeur faible poids tient aussi au cordon sanitaire, qui les écarte des postes de responsabilité. Selon EU Matrix, il place l'influence de la délégation française dans le bas du classement. Le vrai débat porte moins sur la présence que sur ce que le RN vote et défend quand il travaille.",
 empathie="Il est légitime d'attendre de ses élus qu'ils travaillent pour le salaire qu'ils touchent, quel que soit leur parti. C'est une exigence à appliquer à tous, avec des chiffres vérifiables.",
 legitimes=["La présence aux votes en plénière des élus RN est élevée.", "Une partie des eurodéputés RN s'investit davantage depuis 2024.", "Le cordon sanitaire limite mécaniquement les responsabilités qu'ils peuvent obtenir."],
 contre=[
  ("Bardella est présent à presque tous les votes.", "La plénière n'est que la partie visible ; selon Complément d'enquête, il a manqué la majorité des réunions de sa commission, là où s'écrivent les textes."),
  ("On les empêche de travailler avec le cordon sanitaire.", "Le cordon les prive de présidences, pas d'amendements ni de présence en commission ; et depuis 2024 leur groupe a d'ailleurs obtenu des rapports."),
 ],
 questions=["Savais-tu que le taux de présence mis en avant par le RN ne compte que les votes en plénière ?", "Pour juger un élu, préfères-tu regarder sa présence aux votes ou les textes qu'il a écrits ?"],
 limites=["Aucun classement complet d'activité par élu (MEPRanking, Parltrack, données du Parlement) n'a pu être lu : les données portent surtout sur Jordan Bardella.", "L'article du Parisien a été lu dans une copie hébergée par un site tiers ; celui de France 24 dans une reproduction en anglais sans date.", "Les chiffres d'amendements avancés par Jordan Bardella ne sont pas vérifiés de façon indépendante.", "L'affaire des assistants parlementaires est traitée dans une autre fiche."],
 publics={'convaincus': "Le RN aime citer sa présence aux votes, mais la loi européenne s'écrit en commission. Là, Bardella a manqué la majorité des réunions entre 2019 et 2023 selon Complément d'enquête. Ce n'est pas une insulte, c'est un relevé. Si tes élus te représentent, tu as le droit d'exiger qu'ils soient là où se décident les textes.",
  'indecis': "Pour 2019-2024, le reproche est largement documenté. Depuis 2024, une partie des élus RN travaille davantage, et il faut le reconnaître. Le plus utile est de regarder ce qu'ils votent : c'est là que se voient leurs choix."},
 a_actualiser='2027-07-01', raison="Bilans d'activité à mi-mandat de la législature européenne 2024-2029.",
))

# 4 ── Les jeunes préfèrent-ils un régime autoritaire ? ─────────────────────────
D_CEVIPOF_BAROMETRE_2026 = ('d_cevipof_barometre_2026', src("78 % des Français n'ont pas confiance en la politique, selon le baromètre du Cevipof", "Public Sénat (Guillaume Cros), sur le baromètre de la confiance politique du Cevipof", "10 février 2026",
  "https://www.publicsenat.fr/actualites/politique/78-des-francais-nont-pas-confiance-en-la-politique-selon-le-barometre-de-cevipof",
  "Enquête réalisée du 12 au 28 janvier 2026 auprès de 3 166 inscrits. 82 % des Français « continue d'approuver le système démocratique », mais 76 % le jugent « défaillant ». 36 % soutiennent l'idée d'un homme « fort qui n'a pas à se préoccuper du parlement ni des élections » et 20 % sont favorables à un « régime martial ». L'article ne donne pas de ventilation par âge.",
  "Média parlementaire public rendant compte d'une enquête du centre de recherche de Sciences Po.", 'secondaire'))
