D_OBS_DECOLONIALISME_2021 = ('d_obs_decolonialisme_2021', src("Appel de l'Observatoire du décolonialisme et des idéologies identitaires (texte fondateur)", "Observatoire du décolonialisme", "janvier 2021",
  "https://www.decolonialisme.fr/en/call-from-the-observatory-of-decolonialism-and-identity-ideologies/",
  "Le texte fondateur affirme que l'enseignement supérieur fait face à un « militant movement » dont les idéologues veulent « deconstruct » tous les savoirs, et que les doctorants seraient poussés à s'aligner sur les « new mandarins » sous peine de ne jamais obtenir de poste. Il ne présente ni données, ni enquête, ni décompte de cas.",
  "Collectif d'universitaires engagé contre le « wokisme » (source orientée, citée seulement pour attribuer ses thèses).", 'primaire'))

FICHES.append(fiche(
 id='wokisme-universite', affirmation="Le wokisme a pris le contrôle des universités.", volet='services', sous_theme='Université',
 mots_cles=['wokisme universite', 'woke universite', 'universites wokes', 'wokisme fac', 'ideologie a l universite', 'decolonialisme universite', 'cancel culture universite', 'liberte academique'],
 verdict='trompeur', fiabilite='debat',
 resume="Aucune donnée ne montre une « prise de contrôle » : même la commission d'enquête du Sénat, critique envers le militantisme universitaire, constate en 2026 qu'il n'existe « aucun état des lieux objectif et partagé », et l'ancienne ministre Frédérique Vidal reconnaît qu'on ne sait pas si le phénomène est marginal. Des incidents réels existent, comme l'annulation en 2019 d'une conférence de Sylviane Agacinski après des menaces, et ils doivent être condamnés. Mais l'accusation globale repose surtout sur des auditions et des collectifs militants, comme l'Observatoire du décolonialisme, qui ne publient pas de données.",
 contexte="Le mot « wokisme » sert à désigner pêle-mêle les études sur le genre, le racisme ou la colonisation, et les militants qui perturbent des débats. Il a pris le relais de l'accusation d'« islamo-gauchisme » de 2021.",
 explication="Il faut séparer trois choses : l'existence de champs de recherche (genre, études postcoloniales), qui relève de la liberté académique ; des incidents précis d'intimidation, qui sont réels ; et l'idée d'une domination générale, qui demande des données qu'on n'a pas.",
 sources=[D_SENAT_UNIVERSITES_2026, D_PUBLICSENAT_CNRS_2021, D_PUBLICSENAT_AGACINSKI_2019, D_OBS_DECOLONIALISME_2021],
 faits=[
  fait("La commission d'enquête du Sénat constate en 2026 qu'il n'existe « aucun état des lieux objectif et partagé » sur le militantisme à l'université ; Frédérique Vidal regrette qu'aucun élément ne permette de dire si le phénomène est marginal ou s'il s'amplifie.", 'd_senat_universites_2026', '2026', 'France', "Même les critiques du militantisme universitaire n'ont pas de mesure de son ampleur.", 'etabli'),
  fait("Le même rapport sénatorial dénonce une « progression des démarches militantes » et une « confusion croissante entre science et militantisme », et recommande des procédures disciplinaires pour les atteintes à la liberté académique.", 'd_senat_universites_2026', '2026', 'France', "Fait défavorable : une institution officielle juge le problème sérieux, sur la base d'auditions.", 'interpretation'),
  fait("En février 2021, le CNRS a qualifié l'« islamo-gauchisme » de « slogan politique » qui « ne correspond à aucune réalité scientifique », et rejeté la délégitimation des études postcoloniales.", 'd_publicsenat_cnrs_2021', '2021', 'France', "Le principal organisme de recherche refuse ces étiquettes globales.", 'etabli'),
  fait("En octobre 2019, l'université Bordeaux III a déprogrammé une conférence de la philosophe Sylviane Agacinski, opposée à l'extension de la PMA, faute de pouvoir assurer sa sécurité après des menaces.", 'd_publicsenat_agacinski_2019', '2019', 'France', "Des intimidations réelles ont empêché des débats : il faut les reconnaître et les condamner.", 'etabli'),
  fait("Selon un sondage CSA cité par le Sénat, 63 % des Français estiment que les mobilisations collectives perturbent les enseignements à l'université.", 'd_senat_universites_2026', '2026', 'France', "C'est une perception du grand public, pas une mesure de ce qui se passe dans les universités.", 'estimation', '63 %'),
  fait("Le texte fondateur de l'Observatoire du décolonialisme (2021) affirme qu'un mouvement militant veut « déconstruire » tous les savoirs à l'université, sans présenter ni données ni enquête.", 'd_obs_decolonialisme_2021', '2021', 'France', "L'une des principales sources du discours anti-woke est un collectif engagé qui procède par affirmations.", 'etabli'),
 ],
 court="Personne n'a mesuré une « prise de contrôle » : même le Sénat, critique envers le militantisme universitaire, constate qu'il n'existe aucun état des lieux objectif. Il y a des incidents réels, comme une conférence annulée après des menaces, qu'il faut condamner. Mais étudier le genre ou la colonisation, c'est de la recherche, pas une prise de pouvoir.",
 moyen="Il y a des faits réels. En 2019, une conférence de Sylviane Agacinski a été annulée à Bordeaux après des menaces. En 2026, une commission d'enquête du Sénat a dénoncé une progression du militantisme dans les universités et des perturbations de cours et de conférences.\n\nMais la même commission reconnaît qu'il n'existe « aucun état des lieux objectif et partagé », et l'ancienne ministre Frédérique Vidal admet qu'on ne sait pas si le phénomène est marginal. Le CNRS rappelle qu'étudier le genre ou la colonisation est un champ de recherche légitime. Des incidents ne font pas une prise de contrôle : il faut les sanctionner sans jeter le soupçon sur des disciplines entières.",
 detaille="Commençons par ce qui est vrai. Des débats ont été empêchés : en octobre 2019, l'université Bordeaux III a déprogrammé la philosophe Sylviane Agacinski, opposée à l'extension de la PMA, faute de pouvoir assurer sa sécurité après des menaces. En septembre 2026, la commission d'enquête du Sénat sur l'excellence universitaire a dénoncé une « progression des démarches militantes » et des perturbations d'enseignements et de conférences, et recommandé des sanctions disciplinaires. Selon un sondage CSA qu'elle cite, 63 % des Français pensent que les mobilisations perturbent les cours.\n\nMais aucune mesure ne soutient l'idée d'une « prise de contrôle ». Le même rapport constate qu'il n'existe « aucun état des lieux objectif et partagé » ; l'ancienne ministre Frédérique Vidal regrette qu'on ne puisse pas dire si le phénomène est marginal ou s'il s'amplifie. Les constats reposent sur des auditions, dont plusieurs universitaires engagés contre le « wokisme », et la direction de l'enseignement supérieur rappelle que la rigueur dépend de la démarche, pas de l'objet étudié.\n\nLe mot « wokisme » mélange tout : des champs de recherche, comme les études sur le genre ou la colonisation, et des militants qui empêchent des débats. Le CNRS a qualifié en 2021 l'étiquette d'« islamo-gauchisme » de slogan politique sans réalité scientifique. L'Observatoire du décolonialisme, souvent cité, affirme sans présenter de données. Défendre la liberté académique, c'est protéger à la fois les conférenciers menacés et les chercheurs dont on voudrait interdire les sujets.",
 empathie="On peut être choqué de voir une conférence annulée sous la menace, ou craindre que l'université devienne un lieu de pensée unique. Ces inquiétudes méritent une réponse précise, cas par cas, plutôt qu'un slogan.",
 legitimes=["Des conférences ont été annulées ou perturbées sous la pression de militants.", "Une commission d'enquête du Sénat juge le militantisme universitaire en progression.", "La frontière entre recherche et engagement peut être floue dans certains travaux."],
 contre=[
  ("Une conférence a bien été annulée, c'est la preuve.", "C'est la preuve d'un incident grave, à condamner ; pas d'une prise de contrôle des universités, que personne n'a mesurée."),
  ("Le Sénat lui-même le dit.", "Le rapport dénonce une progression du militantisme, mais reconnaît qu'il n'existe aucun état des lieux objectif ; il s'appuie sur des auditions, pas sur une enquête chiffrée."),
 ],
 questions=["Savais-tu que même la commission d'enquête du Sénat dit qu'il n'existe aucun état des lieux objectif du phénomène ?", "Faut-il sanctionner ceux qui empêchent un débat, ou interdire certains sujets de recherche ?"],
 limites=["Le rapport du Sénat a été lu par extraits (texte très long) ; sa partie sur la liberté académique a été lue, pas l'intégralité.", "Aucune étude empirique sur les opinions politiques des universitaires français ni sondage auprès d'eux sur la liberté académique n'a pu être lu.", "Le communiqué du CNRS a été lu à travers Public Sénat ; celui de la Conférence des présidents d'université n'a pas été ouvert.", "L'histoire de l'accusation d'« islamo-gauchisme » est traitée dans la fiche islamo-gauchisme-origine-usages."],
 publics={'convaincus': "Les incidents existent, et je les condamne : empêcher Sylviane Agacinski de parler était inacceptable. Mais même la commission du Sénat, qui partage ton inquiétude, dit qu'il n'existe aucun état des lieux objectif. Si on veut défendre la liberté à l'université, il faut la défendre pour tout le monde, y compris pour ceux qui étudient le genre ou la colonisation.",
  'indecis': "La question est sérieuse : des débats ont été empêchés, et le Sénat s'en inquiète. Mais personne n'a mesuré l'ampleur du phénomène, et étudier des sujets qui dérangent fait partie de la recherche. Le bon repère : sanctionner les intimidations, pas les disciplines."},
 a_actualiser='2027-09-30', raison="Suites données au rapport du Sénat et éventuel état des lieux officiel.",
))

